def img(name,alt='',cls='',eager=False):return f'<img src="assets/{name}" alt="{esc(alt)}" class="{cls}" {"fetchpriority=high" if eager else "loading=lazy"} decoding="async">'
def a(url,text,cls='button',extra=''):return f'<a href="{esc(url)}" class="{cls}" {extra}>{text}<span aria-hidden="true">↗</span></a>'
def eyebrow(text):return f'<p class="eyebrow"><span class="tiny-star" aria-hidden="true">✧</span>{text}</p>'
def heading(kicker,title,text=''):return f'<div class="section-heading"><div>{eyebrow(kicker)}<h2>{title}</h2></div>{f"<p>{text}</p>" if text else ""}</div>'

