def page(name,title,body,description='',preload=''):
 p=f'''<!doctype html><html lang="en" data-theme="light"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#f5f3fb"><title>{esc(title)} | SK Group</title><meta name="description" content="{esc(description or 'Explore a world of mobility and enterprise with the SK Group interface demo.')}"><script>try{{document.documentElement.dataset.theme=localStorage.getItem('sk-universe-theme')==='dark'?'dark':'light'}}catch(e){{}}</script><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="preload" href="assets/fonts/sora.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="base.css?v=universe-1"><link rel="stylesheet" href="universe.css?v=universe-1"><script src="data.js?v=universe-1" defer></script><script src="app.js?v=universe-1" defer></script>{f'<link rel="preload" href="assets/{preload}" as="image" fetchpriority="high">' if preload else ''}</head><body data-page="{name}">{header(name)}<main id="main">{body}</main>{footer()}{dialogs()}</body></html>'''
 (DIST/(name+'.html' if name!='home' else 'index.html')).write_text(p)

