own+=f'''<section class="section-shell ownership-hub">{heading('HOW CAN WE HELP?','Keep moving,<br><span>with a little more confidence.</span>')}<div class="action-grid"><a href="book.html?type=service"><span>01</span><h3>Request a service</h3><p>Share your preferred branch and time.</p><b>Plan your visit ↗</b></a><a href="book.html?type=parts"><span>02</span><h3>Parts & accessories</h3><p>Start a conversation about what you need.</p><b>Make an enquiry ↗</b></a><a href="showrooms.html"><span>03</span><h3>Talk to a showroom</h3><p>Find a local connection for your questions.</p><b>Find your branch ↗</b></a></div><div class="finance-section" id="finance">{heading('PLAN THE POSSIBILITIES','A clearer view<br><span>of your next move.</span>')}<div class="tool-tabs" role="group" aria-label="Choose estimate tool"><button type="button" data-tool="emi" aria-pressed="true">EMI estimate</button><button type="button" data-tool="ev" aria-pressed="false">Running-cost comparison</button></div><div class="calculator" id="emi-tool"><div class="calculator-inputs"><label>Loan amount <span>₹</span><input id="loan-amount" type="number" min="1000" max="100000000" step="1000" value="100000"></label><label>Annual interest rate <span>%</span><input id="loan-rate" type="number" min="0" max="40" step="0.1" value="10"></label><label>Tenure <span>months</span><input id="loan-months" type="number" min="1" max="120" step="1" value="36"></label><p class="fine-print">Use your own loan assumptions. This estimate excludes fees, insurance and taxes. It is not a lender offer.</p></div><div class="calculator-result"><p class="eyebrow">ESTIMATED MONTHLY REPAYMENT</p><strong id="emi-value">₹3,227</strong><div class="loan-breakdown"><p><span>Principal</span><b id="principal-value"></b></p><p><span>Total interest</span><b id="interest-value"></b></p><p><span>Total repayment</span><b id="total-value"></b></p></div><a class="text-link" href="book.html?type=enquiry">Discuss with a showroom ↗</a></div></div><div class="calculator" id="ev-tool" hidden><div class="calculator-inputs"><label>Distance per year <span>km</span><input id="ev-distance" type="number" min="1" max="500000" value="9000"></label><label>Current running cost <span>₹ / km</span><input id="ice-cost" type="number" min="0" max="100" step="0.1" value="3.5"></label><label>Alternative running cost <span>₹ / km</span><input id="electric-cost" type="number" min="0" max="100" step="0.1" value="0.8"></label><p class="fine-print">This compares only the running costs you enter. Purchase cost, maintenance, charging arrangements and other costs are excluded.</p></div><div class="calculator-result"><p class="eyebrow">ANNUAL DIFFERENCE FROM YOUR INPUTS</p><strong id="ev-saving"></strong><div class="loan-breakdown"><p><span>Current annual cost</span><b id="ice-annual"></b></p><p><span>Alternative annual cost</span><b id="ev-annual"></b></p></div><a class="text-link" href="brands.html?brand=montra">Explore Montra Electric ↗</a></div></div></div><section class="official-resources">{heading('INFORMATION FROM THE SOURCE','Your brand.<br><span>Your official resources.</span>')}<div class="resource-links">'''
