booking=f'''<section class="booking-layout section-shell"><aside class="booking-story">{img('royal-journey-2.webp','A Royal Enfield rider in a mountain landscape',eager=True)}<div class="story-shade"></div><div>{eyebrow('YOUR NEXT CHAPTER')}<h1>A small step.<br>A new possibility.</h1><p>Tell us what you have in mind.<br>Let’s make the next move feel easy.</p><span>✧</span></div></aside><section class="booking-panel"><p class="preview-label"><i></i> INTERACTIVE UI PREVIEW · NOTHING IS SENT</p><div class="wizard-progress" aria-label="Request steps"><span class="active" data-step-marker="0">01 <b>Your plan</b></span><span data-step-marker="1">02 <b>The details</b></span><span data-step-marker="2">03 <b>About you</b></span><span data-step-marker="3">04 <b>Review</b></span></div><form id="request-form" inert><fieldset data-step="0"><legend>What brings you here?</legend><p class="muted">Choose the kind of conversation you’d like to begin.</p><div class="purpose-grid">'''
