md='# SK Group — 120 possible website features\n\nUI preview = working frontend screen or interaction. Later phase = an idea to scope for future work. No live backend is connected.\n\n'
for group,items in groups:
 md+='## '+group+'\n\n'
 for f in [x for x in features if x['group']==group]:md+=f"{f['id']}. {f['name']} — {f['status']}\n"
 md+='\n'
(ROOT/'FEATURES.md').write_text(md)
